-- Canonical experiment/replay schema. Adapt types to BigQuery/Postgres as needed.
CREATE TABLE market_product_week (week TEXT,country_code TEXT,category_id INTEGER,entity_id TEXT,gtin TEXT,title TEXT,brand TEXT,rank INTEGER,previous_rank INTEGER,rank_delta INTEGER,relative_demand TEXT,previous_relative_demand TEXT,demand_change TEXT,market_price_min REAL,market_price_max REAL,currency TEXT);
CREATE TABLE keyword_month (month TEXT,country TEXT,language TEXT,keyword TEXT,search_volume INTEGER,competition_index INTEGER,avg_cpc REAL,top_bid_low REAL,top_bid_high REAL,trends_score REAL,trends_30d_delta REAL,trends_yoy_delta REAL);
CREATE TABLE product_day (date TEXT,store TEXT,country TEXT,sku TEXT,gtin TEXT,title TEXT,price REAL,benchmark_price REAL,supplier_cost REAL,supplier_shipping REAL,impressions INTEGER,clicks INTEGER,ad_cost REAL,orders INTEGER,units INTEGER,revenue REAL,cogs REAL,gross_profit REAL,payment_fees REAL,refunds REAL,chargebacks REAL,shipping_cost REAL,contribution_profit REAL);
CREATE TABLE action_log (timestamp TEXT,store TEXT,entity_type TEXT,entity_id TEXT,action_type TEXT,before_json TEXT,after_json TEXT,hypothesis TEXT,reason TEXT,actor TEXT,expected_metric TEXT,expected_direction TEXT,evaluation_date TEXT);
CREATE TABLE experiment (experiment_id TEXT,start_date TEXT,end_date TEXT,treatment TEXT,control TEXT,primary_metric TEXT,guardrail_metrics TEXT,pre_period TEXT,post_period TEXT,effect_size REAL,confidence REAL,decision TEXT);
CREATE TABLE store_day (date TEXT,store TEXT,orders INTEGER,revenue REAL,cogs REAL,ad_spend REAL,supplier_shipping REAL,payment_fees REAL,refunds REAL,chargebacks REAL,software REAL,support REAL,gross_profit REAL,contribution_profit REAL,cash_profit REAL,processor_balance REAL,supplier_payables REAL);
